insert into plan_adrs
  (number, slug, title, adr_status, decided_on, deciders, summary, url, read_in_full)
values
  (1, 'full-stack-replatform', 'Replatform Staffility from ServiceNow to a Purpose-Built Full Stack', 'accepted', '2026-07-15'::date, 'Josh Alimi', 'Leave ServiceNow. Angular front end, Go API, PostgreSQL system of record plus Neo4j, Entra ID for authentication with Staffility-owned RBAC. The cost taken on knowingly: they no longer inherit ServiceNow GCC''s FedRAMP authorization, and establishing their own hosting and compliance posture is open question OQ-1 and the program''s highest-risk item.', 'https://dev.azure.com/ipt/Staffility/_git/staffility-go?path=/docs/raw-sources/070-decisions/ADR-001-full-stack-replatform.md&version=GBmain&_a=preview', true),
  (2, 'dual-datastore', 'Dual Datastore: PostgreSQL for Content, Neo4j for Relationships', 'accepted', '2026-07-15'::date, 'Josh Alimi', 'PostgreSQL is the system of record — all content, configuration and PII, row-level security on tenant_id. Neo4j is a derived relationship engine carrying no PII, populated only by a projector consuming a transactional outbox, rebuildable per tenant. Feature code never writes to Neo4j. If the two disagree, PostgreSQL wins and the graph reprojects.', 'https://dev.azure.com/ipt/Staffility/_git/staffility-go?path=/docs/raw-sources/070-decisions/ADR-002-dual-datastore.md&version=GBmain&_a=preview', true),
  (3, 'agent-runtime', 'Separate Python Agent Runtime Behind the Knowledge APIs', 'superseded', '2026-07-15'::date, 'Josh Alimi', 'Amended and largely withdrawn by ADR-009: the Python runtime is gone and the API-only boundary is given up. Its operating invariants survive — agents never sit in the synchronous path, structured output only, propose don''t impose, provider-abstracted, audited, tenant-scoped. Not read in full; summarised from ADR-009''s ''What ADR-003 Keeps'' table, which enumerates every invariant and marks each Kept or Withdrawn.', 'https://dev.azure.com/ipt/Staffility/_git/staffility-go?path=/docs/raw-sources/070-decisions/ADR-003-agent-runtime.md&version=GBmain&_a=preview', false),
  (4, 'multi-tenancy', 'Single Multi-Tenant Platform for All Customer Companies', 'accepted', '2026-07-15'::date, 'Josh Alimi', 'One multi-tenant platform, shared schema, every tenant-owned row carries tenant_id, isolation by API RBAC plus PostgreSQL row-level security. IPTA is tenant #1, not a special case in code. No per-customer forks. Cross-tenant visibility only via consented collaborations with identity anonymised across boundaries. If a customer ever demands physical isolation, that is a new ADR, not silent divergence.', 'https://dev.azure.com/ipt/Staffility/_git/staffility-go?path=/docs/raw-sources/070-decisions/ADR-004-multi-tenancy.md&version=GBmain&_a=preview', true),
  (5, 'session-based-authorization', 'Session-Based Authorization, Entra ID for Authentication Only', 'accepted', '2026-07-28'::date, 'David Speirs', 'A Postgres-backed sessions table is the single authorization mechanism for every identity. Entra is verified once, at session creation, not on every request; candidates get platform-native password accounts. HttpOnly Secure cookie, CSRF by SameSite plus a required custom header. No Redis — Postgres is authoritative, and replica count alone does not justify an operational dependency.', 'https://dev.azure.com/ipt/Staffility/_git/staffility-go?path=/docs/raw-sources/070-decisions/ADR-005-session-based-authorization.md&version=GBmain&_a=preview', true),
  (6, 'two-pillar-product-focus', 'Two-Pillar Product Focus: Staffility is Talent + Community', 'accepted', '2026-07-28'::date, 'Josh Alimi', 'Staffility is two pillars, Talent and Community. Intelligence is not a pillar, it is the differentiator inside both. Operations is not a pillar either. The focus test governs everything: does this strengthen the Talent and Community mission? A ''no'' is relocated, not refused — to a fork, a separate product, or a shared-services capability reusing the same stack, architecture and platform components.', 'https://dev.azure.com/ipt/Staffility/_git/staffility-go?path=/docs/raw-sources/070-decisions/ADR-006-two-pillar-product-focus.md&version=GBmain&_a=preview', true),
  (7, 'brain-architecture', 'Brain Architecture: Standardize the Pattern, Not the Tooling', 'accepted', '2026-07-28'::date, 'Josh Alimi', 'The org standard is the LLM Wiki operating pattern and the Open Knowledge Format v0.1 — a directory of markdown with YAML front matter whose only required field is type. Hosting and agent runtime are chosen per brain to match its audience. Three stacks are expected: the Program Brain on markdown + git + Claude Code, a System Brain on an Azure database, and M365 + Copilot brains as an experiment. Federation — the Knowledge Fabric — is explicitly deferred and its security model is undefined.', 'https://dev.azure.com/ipt/Staffility/_git/staffility-go?path=/docs/raw-sources/070-decisions/ADR-007-brain-architecture.md&version=GBmain&_a=preview', true),
  (8, 'platform-communications', 'Platform Communications: Azure Communication Services for Outbound Email', 'accepted', '2026-07-28'::date, 'Josh Alimi', 'Outbound email through Azure Communication Services, authenticated by managed identity — no API key, nothing new in either Key Vault. Every send goes through a provider-agnostic internal/mail.Mailer seam. Delivery is a transactional outbox drained by a scheduled job, never an inline send. The outbox stores a template id and parameters, never a rendered body, and the drainer sets RLS context per recipient before rendering. Postmark is the documented escape hatch.', 'https://dev.azure.com/ipt/Staffility/_git/staffility-go?path=/docs/raw-sources/070-decisions/ADR-008-platform-communications.md&version=GBmain&_a=preview', true),
  (9, 'inference-gateway', 'Inference Gateway: Go Runtime, Provider Seam, Job-Backed Invocation', 'accepted', '2026-07-29'::date, 'Josh Alimi', 'Every LLM call goes through internal/inference.Provider — one OpenAI-protocol implementation serving Azure AI Foundry, OpenRouter and local runners. Invocation is job-backed, never inline: inference_jobs carries the lifecycle, model, prompt version, tokens, latency and cost, with a child inference_calls table because retry-once means one job makes several billed calls. Endpoints, models and role bindings are database rows managed by an admin. Prompts are versioned immutably, and production activation requires a recorded eval pass. Per-tenant quota and a per-job token ceiling ship with the feature, as a security control.', 'https://dev.azure.com/ipt/Staffility/_git/staffility-go?path=/docs/raw-sources/070-decisions/ADR-009-inference-gateway.md&version=GBmain&_a=preview', true),
  (10, 'developer-database-access', 'Developer and Operator Access to Environment Databases', 'proposed', '2026-07-30'::date, 'Josh Alimi + team', 'STILL OPEN. Nine options, A through I, each costed from the Azure retail prices API, with a For, an Against, and a split recommendation — nonprod one way, production another. The dev database has no public endpoint and no human way to look at the data in it. Carries a clock: ''Decide G soon or not at all — its cost rises once dev holds real data.'' Written 2026-07-30 and still Proposed.', 'https://dev.azure.com/ipt/Staffility/_git/staffility-go?path=/docs/raw-sources/070-decisions/ADR-010-developer-database-access.md&version=GBmain&_a=preview', true),
  (11, 'context-first-navigation', 'Context-First Navigation', 'accepted', '2026-08-10'::date, 'Michael Crivellaro, frontend team', 'Three levels, one job each: a context switcher for which hat the user is wearing, a contextual sidebar of grouped flat destinations each one click deep, and in-page tabs reserved for facets of a single object. A destination lives in exactly one context. Cross-context movement is explicit — a switcher or a command palette, never a duplicate nav entry. Identity is not a context. Triggered by a team complaint that one flat sidebar mixed three paradigms with no primary axis.', 'https://dev.azure.com/ipt/Staffility/_git/staffility-go?path=/docs/raw-sources/070-decisions/ADR-011-context-first-navigation.md&version=GBmain&_a=preview', true),
  (12, 'collaboration-names-the-person', 'A Collaboration Discloses the Person It Names, and Consent Lives Outside the System', 'accepted', '2026-08-20'::date, 'Josh Alimi', 'Identity crosses a company boundary for exactly one person — the one a collaboration names — and only while it is accepted. Enforced in the database, not in application code. Fixes a real hole: one accepted collaboration used to unmask every staff user at each company to the other, bidirectionally and roster-wide. Consent is obtained organisationally, outside the platform; the written-but-never-read consent column stays as a seam if a jurisdiction ever requires the in-system version.', 'https://dev.azure.com/ipt/Staffility/_git/staffility-go?path=/docs/raw-sources/070-decisions/ADR-012-collaboration-names-the-person.md&version=GBmain&_a=preview', true)
insert into plan_reconcile (set_key, verdict, adr_refs, note, action)
values
  ('control-plane-hosting', 'settled', '{1}'::integer[], 'ADR-001 settles the stack — Angular, Go, Azure — and the 2026-08-05 overview confirms web app, API and jobs all run in Azure Container Apps. Our ten hosting options were researched against a question their side already answered.', 'Adopt Azure Container Apps as the destination. Render stays as the prototype''s home until the Integrator migrates; that is a difference of timing, not of direction.'),
  ('postgres-host', 'settled', '{1,2}'::integer[], 'Azure Database for PostgreSQL Flexible Server, with row-level security on tenant_id doing the isolation. ADR-002 also adds Neo4j as a derived, PII-free relationship engine fed by a transactional outbox — a whole component the Integrator has no equivalent of and has never costed.', 'Adopt Flexible Server. Decide separately whether the Integrator ever needs the graph half; today it does not.'),
  ('job-scheduling', 'settled', '{8,9}'::integer[], 'Azure Container Apps Jobs on a one-minute cron, draining until empty, so frequency bounds first-item latency rather than throughput. ADR-009 prices the alternative explicitly: an always-on worker reaches about one-second pickup for roughly $35/month/env against $3.', 'Adopt. Note the pattern too — the transactional outbox, where the triggering change and the queue row commit in the same transaction. That is stronger than anything the Integrator has.'),
  ('admin-auth', 'settled', '{5}'::integer[], 'Not ''use Entra'' as we had assumed. ADR-005 decides a Postgres-backed sessions table as the ONE authorization mechanism, with Entra verified once at session creation and platform-native password accounts for people who have no Entra identity. Decided by David Speirs, not Josh.', 'Adopt. The Integrator''s bcrypt-plus-JWT is closer to this than to a pure Entra design, so convergence is a smaller step than it looked — swap the JWT for a sessions row and the shape matches.'),
  ('tenant-credentials', 'additive', '{8,9}'::integer[], 'ADR-009''s Deferred list, verbatim: ''Per-tenant endpoints and keys — a tenant bringing its own model.'' They consciously postponed it. That is exactly migration 005. Meanwhile their pattern is already proven on ats_sync_config.api_key BYTEA with internal/encryption, keys write-only across the API, and a deliberate two-Key-Vault split so the migration runner and the API cannot read each other''s secrets.', 'This is the Integrator''s strongest contribution. Build 005 to their pattern — encrypted at rest, write-only across the API, one master key in a vault — so it is adoptable rather than parallel.'),
  ('regulated-plane', 'open', '{1,9}'::integer[], 'OPEN ON BOTH SIDES, and it is their highest-risk item. ADR-001: leaving ServiceNow GCC forfeited an inherited FedRAMP authorization, and establishing their own posture is open question OQ-1. ADR-009 already flags that Foundry model availability in Azure Government is thinner than Document Intelligence''s. Our own research adds two things their documents do not have: FedRAMP Moderate is being dissolved into Classes A-D, mandatory 2027-01-01, and Model Router is not in Azure Government at all.', 'The single highest-value thing the workbench brings to Wednesday. Nine costed options and a fact base neither side had written down.'),
  ('ai-gateway', 'settled', '{9,3}'::integer[], 'ADR-009 decides it completely: a Go seam, internal/inference.Provider, one OpenAI-protocol implementation serving Azure AI Foundry, OpenRouter and local runners, with Azure''s protocol quirks quarantined in one adapter file. It also settles the structured-output question the same way the Integrator did — request JSON mode, validate the schema in the seam, retry once, treat native strict mode as an optimisation.', 'Adopt. Foundry as default, OpenRouter as a configured alternative — which is what the workbench already had pre-selected, so nothing moves.'),
  ('ai-observability', 'settled', '{9}'::integer[], 'No third-party observability vendor. inference_jobs plus a child inference_calls table, per-call cost attributed to tenant, user and impersonator from the first call because attribution cannot be backfilled. Usage data is admin-only for now, deliberately, so the commercial model stays undecided.', 'Adopt, and steal it. The Integrator''s ai_agent_runs is one row per job and therefore undercounts spend exactly when a retry fires — which is exactly when output quality is degrading.'),
  ('doc-scanning', 'settled', '{9}'::integer[], 'ADR-009 Decision 6: Azure AI Document Intelligence, called as an HTTP service from Go under managed identity. It replaces a documented ServiceNow reliability problem and removes the last substantive argument for a Python runtime.', 'Adopt for Staffility. The Integrator''s separate local poppler-plus-tesseract scanner stays as it is — it exists so contracts never leave the machine, which is a different problem from parsing a resume.'),
  ('ats-integration', 'open', '{9}'::integer[], 'Partly built, no vendor decided. ats_sync_config already exists and ADR-009 cites its encrypted api_key column as the precedent to follow; ADR-011 shows an Admin > Companies > ATS Sync screen. But no ADR names a vendor, and the 2026-08-05 overview says only that listings are pulled from partner ATS APIs on a schedule.', 'Real open question. Bring the nine researched options — and the finding that Bullhorn charges the integrator, not the client: $5,000/yr partner fee, $1,000-4,000 validation, 15% revenue share past one customer.'),
  ('m365-ingest', 'out-of-scope', '{5}'::integer[], 'Nothing in the twelve ADRs touches it. Entra appears only as an authentication step in ADR-005. Pulling mail, calendar and files out of three tenants is an Integrator concern, not a Staffility one.', 'Ours alone. Keep the research; do not spend Wednesday on it.'),
  ('unified-api', 'out-of-scope', '{6}'::integer[], 'No ADR contemplates a unified-API layer, and their ATS route is a direct integration behind their own seam. By ADR-006''s focus test a general integration layer is not Talent or Community.', 'Ours alone, and our own research already said build-direct until the connector count justifies otherwise.'),
  ('financial-aggregation', 'out-of-scope', '{6}'::integer[], 'Fails the focus test outright. Nothing in Staffility touches bank data.', 'Integrator and Bills-Master-Plan only. Note that six of the nine options are quote-only, so this category cannot be budgeted without sales calls.'),
  ('personal-finance-sync', 'out-of-scope', '{6}'::integer[], 'Same as above, and more so — this is Bill''s own bookkeeping, not a platform capability.', 'Integrator only. Tiller already works and is already connected.'),
  ('transcript-capture', 'open', '{7}'::integer[], 'Not a Staffility product capability, but it IS a live open question in ADR-007: ''Is one-source-at-a-time with a human in the loop, or fully automated transcript ingestion, the operating model?'' The Program Brain''s current rule says the former; their sprint demo targets the latter, and the automated model has no design and no quality gate.', 'Genuinely useful to bring. Our eight researched options carry the fact that decides it — retention. Which vendors keep recordings, for how long, and whether that can be turned off.'),
  ('notify-publish', 'settled', '{8}'::integer[], 'Azure Communication Services Email, managed identity, no stored secret, behind an internal/mail.Mailer seam, delivered by a transactional outbox. ADR-008 rejects third-party ESPs on a named ground — a second data-processing boundary for PII and an open question about US-commercial SaaS in a Government port — while naming Postmark as the documented escape hatch.', 'Adopt. Our own research independently found the same trap they avoided: SendGrid''s permanent free tier ended 2025-07-26, and Microsoft retired Teams incoming webhooks in May 2026.')
insert into plan_issues
  (slug, title, question, why, if_undecided, owner, issue_status, rank, adr_refs)
values
  ('oq1-hosting-compliance', 'OQ-1: hosting and compliance — their highest-risk item, open since July', 'Who owns establishing the compliance posture that leaving ServiceNow GCC gave up, and by when?', 'ADR-001 names it ''open question OQ-1 and the program''s highest-risk item'' and it has been open since 2026-07-15. Three facts have moved since it was written, and none are in their documents: FedRAMP Moderate is being dissolved into Classes A-D with the new structure mandatory 2027-01-01; Azure AI Foundry''s Model Router is not available in Azure Government at all; and per DoD CIO FAQ E-A4, holding a regulated tenant''s credentials is itself a trigger, with no customer-key carve-out.', 'Every architecture decision keeps being made against an unknown compliance target, and the cost of unwinding one rises monthly. The Integrator''s migration 005 lands squarely on the credentials trigger.', 'Josh + Bill', 'open', 10, '{1,9}'::integer[]),
  ('adr-010-is-aging', 'ADR-010 is still Proposed, and it has a clock on it', 'Decide developer and operator database access — and do it as the first live test of this tool.', 'Nine costed options, written 2026-07-30, still Proposed 24 days later. It carries its own deadline: ''Decide G soon or not at all — its cost rises once dev holds real data.'' It is also, structurally, exactly what this workbench does — priced options with a For, an Against and a recommendation — hand-built in markdown for one decision.', 'Option G stops being free the moment dev holds real data, and the recommendation quietly expires without anyone noticing. Meanwhile nobody can look at the dev database at all.', 'Josh + team', 'open', 20, '{10}'::integer[]),
  ('where-does-integrator-fit', 'Is the Integrator in Staffility, beside it, or separate?', 'Apply ADR-006''s focus test to the Integrator and say the answer out loud.', 'The focus test asks whether something strengthens the Talent and Community mission. The Integrator is neither — so it is a ''no''. But ADR-006 is explicit that the ''no'' branch is load-bearing: relocated, not refused, to a fork or a separate product ''reusing the same stack, architecture, agent patterns, and platform components''. It also says the focus test ''starts producing relocated work immediately'' and that the module ecosystem and Innovation Factory, its named destinations, are both Phase 3+.', 'The Integrator keeps being built without a stated relationship to the platform, and the module ecosystem stays Phase 3 while the first piece of relocated work already exists.', 'Bill + Josh', 'open', 30, '{6}'::integer[]),
  ('one-platform-or-two', 'One platform or two? Node versus Go, and whether the graph matters', 'Does the Integrator converge on Go and the dual datastore, or stay Node and Postgres-only as a deliberate difference?', 'ADR-001 and ADR-009 decide Go, one runtime, one deploy story. ADR-002 adds Neo4j. The Integrator is Node and TypeScript on Postgres alone. Neither is wrong; what is wrong is leaving it unsaid, because then every future overlap reads as drift instead of as a choice.', 'Two teams write two gateways, two run ledgers and two credential stores, and each discovers the other''s later.', 'Bill + Josh', 'open', 40, '{1,2,9}'::integer[]),
  ('two-brains', 'Two Brains, and the federation question neither has answered', 'How does the Digital Brain blueprint relate to ADR-007''s brain standard — and who answers the federation question?', 'ADR-007 already sets an org standard: the LLM Wiki pattern plus Open Knowledge Format v0.1, with tooling chosen per brain. It then defers federation — the Knowledge Fabric — and lists as an open question ''how do brains relate to each other?'' with the security model ''undefined''. That deferred question is precisely what the Digital Brain blueprint is about: cross-tenant context, corrections, provable trimming, approved action.', 'Bill''s strategic work and Josh''s accepted standard stay in separate documents that each assume the other does not exist.', 'Bill + Josh', 'open', 50, '{7}'::integer[]),
  ('who-builds-tenant-credentials', 'Per-tenant credentials: they deferred it, we are building it', 'Is migration 005 the shared answer, built to their pattern, or two separate implementations?', 'ADR-009 defers ''per-tenant endpoints and keys — a tenant bringing its own model'' and names its cost: per-tenant secrets, quota, and blast-radius isolation. The Integrator''s migration 005 is exactly that. Their pattern already exists in ats_sync_config with internal/encryption, keys write-only across the API, and a two-vault split.', 'The Integrator builds a credential store shaped differently from the one Staffility will eventually need, and the second one is a rewrite.', 'Bill + Josh', 'open', 60, '{9,8}'::integer[]),
  ('four-fixes-we-owe-ourselves', 'Four things to steal from ADR-009 into the Integrator', 'Accept these four as Integrator backlog items?', 'A child inference_calls table, because one row per job undercounts spend the moment a retry fires. Model unit prices NOT NULL, so a cost snapshot can never silently be zero. Per-tenant quota and a per-job token ceiling treated as a security control rather than a budget line. Prompts versioned immutably with activation separate from editing and a recorded eval pass required for production.', 'The Integrator''s cost ledger is quietly wrong in exactly the circumstances that matter, and prompts stay unversioned.', 'Bill', 'open', 70, '{9}'::integer[]),
  ('which-tracker-is-the-tracker', 'The board and the register disagree about what is being tracked', 'Is the requirements register the tracker for the 2.0 work, and should Boards reflect it at all?', 'The Staffility board holds 31 Product Backlog Items of 1.0 product work — referral milestones, LinkedIn parsing, a resume-parsing bug — on the Scrum process, newest sprint 26-12 ending 26 June. The 2.0 replatform is not on it. The register in docs/raw-sources/010-requirements/requirements.md carries the real seven-state flow with permanent requirement IDs.', 'Anyone outside the repo reads the board and concludes the programme stalled in June.', 'Josh', 'open', 80, '{}'::integer[]),
  ('how-we-stay-in-sync', 'How this reconciliation stays true after ADR-013 is written', 'Add one step to the Staffility pipeline that pushes the ADR index and register statuses to the Integrator?', 'This whole sheet is a snapshot taken on 2026-08-23. The moment an ADR is added or a register row moves, it is wrong while still looking authoritative. Pulling from Azure DevOps needs a stored credential we have nowhere safe to keep, and global personal access tokens are decommissioned 2026-12-01. Pushing from their pipeline needs no credential on our side and uses machinery both sides already have.', 'The reconciliation goes stale silently, which is the exact failure this project has caught four times in two days.', 'Bill + Josh', 'open', 90, '{}'::integer[]),
  ('the-money', 'The number is a floor, not an estimate', 'Are we comfortable planning against a figure that excludes two whole sales-gated categories?', 'The chosen stack prices at roughly $79/month at default load. Two chosen options are quote-only and excluded by design. Two entire categories are sales-gated — six of nine financial-aggregation options and seven of nine ATS options publish no rate at all — and any one of those conversations can exceed the whole priced total.', 'A floor gets quoted as a budget.', 'Bill', 'open', 100, '{}'::integer[]),
  ('stale-docs', 'Three documents that have drifted, named gently', 'Worth a cleanup pass?', 'docs/raw-sources/README.md still says ''This repo contains no application code — implementation happens in separate repos'' while the root holds backend/, frontend/ and infra/. ADR-006 itself flags overview.md, prd.md and intelligence-prd.md as stale on framing and calls fixing them ''the highest-priority follow-up from this ADR''. Same species as the 76d444d footer in our own tool that Bill caught tonight.', 'A new developer reads the README on day one and starts in the wrong place.', 'Josh', 'open', 110, '{6}'::integer[])
